import { useEffect, useRef, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

export interface ActivityItem {
  id: string;
  team_id: string;
  actor_id: string | null;
  action: string;
  entity_type: string | null;
  entity_id: string | null;
  metadata: Record<string, any>;
  created_at: string;
}

const PAGE_SIZE = 50;

/** Map action strings to the filter tab categories */
const ACTION_FILTER_MAP: Record<string, string[]> = {
  Tasks: ["task_created", "task_completed"],
  Notes: ["note_added"],
  Stages: ["stage_changed"],
  Applications: ["application_received"],
  Members: ["member_joined"],
};

function getActionsForFilter(filter: string): string[] | null {
  if (filter === "All") return null;
  return ACTION_FILTER_MAP[filter] ?? null;
}

export function useActivityFeed(
  teamId: string | null,
  filter: string = "All"
) {
  const queryClient = useQueryClient();
  const actions = getActionsForFilter(filter);
  const queryKey = ["activity-feed", teamId, filter];

  // Cursor for pagination (oldest created_at in current set)
  const [before, setBefore] = useState<string | null>(null);
  const [hasMore, setHasMore] = useState(false);

  // Accumulate pages locally so "Load more" appends
  const [allActivities, setAllActivities] = useState<ActivityItem[]>([]);
  const initialLoaded = useRef(false);

  const { data, isLoading, isFetching, error } = useQuery<ActivityItem[]>({
    queryKey: [...queryKey, before],
    queryFn: async () => {
      if (!teamId) return [];

      let q = (supabase as any)
        .from("activity_log")
        .select("*")
        .eq("team_id", teamId)
        .order("created_at", { ascending: false })
        .limit(PAGE_SIZE + 1); // +1 to detect hasMore

      if (actions && actions.length > 0) {
        q = q.in("action", actions);
      }
      if (before) {
        q = q.lt("created_at", before);
      }

      const { data: rows, error } = await q;
      if (error) throw error;
      return (rows ?? []) as ActivityItem[];
    },
    enabled: !!teamId,
    staleTime: 30_000,
  });

  // Merge pages when data arrives
  useEffect(() => {
    if (!data) return;

    const more = data.length > PAGE_SIZE;
    const page = more ? data.slice(0, PAGE_SIZE) : data;
    setHasMore(more);

    if (!before) {
      // First page — reset
      setAllActivities(page);
      initialLoaded.current = true;
    } else {
      // Subsequent page — append
      setAllActivities((prev) => {
        const existingIds = new Set(prev.map((a) => a.id));
        const fresh = page.filter((a) => !existingIds.has(a.id));
        return [...prev, ...fresh];
      });
    }
  }, [data]);

  // Reset when teamId or filter changes
  useEffect(() => {
    setBefore(null);
    setAllActivities([]);
    initialLoaded.current = false;
  }, [teamId, filter]);

  // Realtime subscription — invalidate first-page query on new inserts
  useEffect(() => {
    if (!teamId) return;

    const channel = supabase
      .channel(`activity-log-${teamId}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "activity_log",
          filter: `team_id=eq.${teamId}`,
        },
        (payload) => {
          const newItem = payload.new as ActivityItem;
          // Prepend to the displayed list immediately (optimistic)
          setAllActivities((prev) => {
            if (prev.some((a) => a.id === newItem.id)) return prev;
            return [newItem, ...prev];
          });
          // Also invalidate so first-page re-fetches on next stale check
          queryClient.invalidateQueries({ queryKey: ["activity-feed", teamId, filter] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [teamId, filter, queryClient]);

  function loadMore() {
    if (!hasMore || isFetching) return;
    const last = allActivities[allActivities.length - 1];
    if (last) setBefore(last.created_at);
  }

  return {
    activities: allActivities,
    isLoading: isLoading && allActivities.length === 0,
    isFetching,
    hasMore,
    loadMore,
    error,
  };
}

import { useState, useRef, useEffect } from "react";
import { useCandidateNotes, type NoteType } from "@/hooks/useCandidateNotes";
import { useAuth } from "@/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { MessageSquare, Trash2, Loader2, AtSign } from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { cn } from "@/lib/utils";
import { toast } from "sonner";

const NOTE_TYPE_STYLES: Record<NoteType, { label: string; className: string }> = {
  general: { label: "General", className: "bg-muted text-muted-foreground" },
  positive: { label: "Positive", className: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400" },
  concern: { label: "Concern", className: "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400" },
  flag: { label: "Flag", className: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400" },
};

interface CandidateNotesPanelProps {
  resumeId: string;
  jobId: string;
  teamMembers?: { user_id: string; email?: string }[];
}

/** Renders note content with @mentions highlighted in primary color */
function renderNoteContent(text: string) {
  const parts = text.split(/(@\S+)/g);
  return parts.map((part, i) =>
    part.startsWith("@") ? (
      <span key={i} className="text-primary font-medium">{part}</span>
    ) : (
      <span key={i}>{part}</span>
    )
  );
}

export default function CandidateNotesPanel({ resumeId, jobId, teamMembers = [] }: CandidateNotesPanelProps) {
  const { user } = useAuth();
  const { notes, isLoading, addNote, deleteNote, currentUserId } = useCandidateNotes(resumeId, jobId);
  const [content, setContent] = useState("");
  const [noteType, setNoteType] = useState<NoteType>("general");

  // Mention state
  const [mentions, setMentions] = useState<string[]>([]);
  const [showMentionPopover, setShowMentionPopover] = useState(false);
  const [mentionSearch, setMentionSearch] = useState("");
  const [mentionAnchor, setMentionAnchor] = useState<{ top: number; left: number } | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const mentionPopoverRef = useRef<HTMLDivElement>(null);

  // Close popover on outside click
  useEffect(() => {
    if (!showMentionPopover) return;
    const handler = (e: MouseEvent) => {
      if (
        mentionPopoverRef.current &&
        !mentionPopoverRef.current.contains(e.target as Node) &&
        textareaRef.current &&
        !textareaRef.current.contains(e.target as Node)
      ) {
        setShowMentionPopover(false);
        setMentionSearch("");
      }
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [showMentionPopover]);

  /** Detect @mention trigger in textarea */
  const handleContentChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const val = e.target.value;
    setContent(val);

    const cursorPos = e.target.selectionStart ?? val.length;
    const textBeforeCursor = val.slice(0, cursorPos);

    // Find the last @ that's either at start or after a space
    const atMatch = textBeforeCursor.match(/(^|\s)@(\S*)$/);
    if (atMatch) {
      const query = atMatch[2];
      setMentionSearch(query);
      setShowMentionPopover(true);
      // Position the dropdown relative to the textarea
      if (textareaRef.current) {
        const rect = textareaRef.current.getBoundingClientRect();
        const parentRect = textareaRef.current.parentElement?.getBoundingClientRect() ?? rect;
        setMentionAnchor({
          top: rect.bottom - parentRect.top + 4,
          left: 0,
        });
      }
    } else {
      setShowMentionPopover(false);
      setMentionSearch("");
    }
  };

  /** Insert @email at cursor and add user_id to mentions */
  const handleMentionSelect = (member: { user_id: string; email?: string }) => {
    if (!textareaRef.current) return;

    const label = member.email ?? member.user_id.slice(0, 8);
    const cursorPos = textareaRef.current.selectionStart ?? content.length;
    const textBeforeCursor = content.slice(0, cursorPos);
    const textAfterCursor = content.slice(cursorPos);

    // Replace the partial @query with the resolved @label
    const replaced = textBeforeCursor.replace(/(^|\s)@\S*$/, (match) => {
      const prefix = match.startsWith("@") ? "" : match[0];
      return `${prefix}@${label} `;
    });

    const newContent = replaced + textAfterCursor;
    setContent(newContent);

    // Track the user_id (avoid duplicates)
    if (!mentions.includes(member.user_id)) {
      setMentions((prev) => [...prev, member.user_id]);
    }

    setShowMentionPopover(false);
    setMentionSearch("");

    // Restore focus to textarea
    requestAnimationFrame(() => {
      textareaRef.current?.focus();
    });
  };

  // Filter team members: exclude current user, filter by search query
  const filteredMembers = teamMembers.filter((m) => {
    if (m.user_id === user?.id) return false;
    if (!mentionSearch) return true;
    const label = (m.email ?? m.user_id).toLowerCase();
    return label.includes(mentionSearch.toLowerCase());
  });

  const handleSubmit = async () => {
    const trimmed = content.trim();
    if (!trimmed) return;
    try {
      await addNote.mutateAsync({ content: trimmed, noteType, mentions });
      setContent("");
      setMentions([]);
      toast.success("Note added");
    } catch {
      toast.error("Failed to add note");
    }
  };

  const handleDelete = async (noteId: string) => {
    try {
      await deleteNote.mutateAsync(noteId);
      toast.success("Note deleted");
    } catch {
      toast.error("Failed to delete note");
    }
  };

  const getAuthorName = (authorId: string): string => {
    if (authorId === user?.id) return "You";
    // Try to find teammate's email from teamMembers
    const member = teamMembers.find((m) => m.user_id === authorId);
    return member?.email ? member.email.split("@")[0] : "Teammate";
  };

  const getInitials = (authorId: string) => {
    if (authorId === user?.id) {
      const email = user?.email ?? "";
      const name = email.split("@")[0];
      return name.slice(0, 2).toUpperCase();
    }
    const member = teamMembers.find((m) => m.user_id === authorId);
    if (member?.email) return member.email.slice(0, 2).toUpperCase();
    return "TM";
  };

  return (
    <div className="rounded-lg border border-border overflow-hidden">
      {/* Panel header — matches StrengthsGapsPanel style */}
      <div className="bg-muted/60 px-4 py-2.5 flex items-center gap-2 border-b border-border">
        <MessageSquare className="h-4 w-4 text-muted-foreground" />
        <span className="text-sm font-semibold text-foreground">Team Notes</span>
        {notes.length > 0 && (
          <span className="ml-auto text-xs font-medium text-muted-foreground bg-muted px-2 py-0.5 rounded-full">
            {notes.length}
          </span>
        )}
      </div>

      <div className="p-4 space-y-3 bg-card">
        {/* Notes list */}
        {isLoading ? (
          <div className="flex items-center gap-2 text-xs text-muted-foreground py-2">
            <Loader2 className="h-3.5 w-3.5 animate-spin" /> Loading notes...
          </div>
        ) : notes.length > 0 ? (
          <div className="space-y-2 max-h-80 overflow-y-auto">
            {notes.map((note) => (
              <div key={note.id} className="rounded-lg border border-border bg-muted/20 p-3 space-y-1.5">
                <div className="flex items-center gap-2">
                  <div className="h-6 w-6 rounded-full bg-primary/10 text-primary flex items-center justify-center text-xs font-bold shrink-0">
                    {getInitials(note.author_id)}
                  </div>
                  <span className="text-xs text-muted-foreground truncate">
                    {getAuthorName(note.author_id)}
                  </span>
                  <span className="text-xs text-muted-foreground/60">
                    {formatDistanceToNow(new Date(note.created_at), { addSuffix: true })}
                  </span>
                  <span className={cn("text-xs px-1.5 py-0.5 rounded-full font-medium", NOTE_TYPE_STYLES[note.note_type as NoteType]?.className)}>
                    {NOTE_TYPE_STYLES[note.note_type as NoteType]?.label ?? note.note_type}
                  </span>
                  {note.author_id === currentUserId && (
                    <button
                      onClick={() => handleDelete(note.id)}
                      className="ml-auto text-muted-foreground/50 hover:text-destructive transition-colors"
                      aria-label="Delete note"
                    >
                      <Trash2 className="h-3 w-3" />
                    </button>
                  )}
                </div>
                <p className="text-sm text-foreground leading-relaxed">
                  {renderNoteContent(note.content)}
                </p>
              </div>
            ))}
          </div>
        ) : null}

        {/* Add note form */}
        <div className="space-y-2 relative">
          {/* Hint when team members are available */}
          {teamMembers.length > 1 && (
            <p className="text-xs text-muted-foreground flex items-center gap-1">
              <AtSign className="h-3 w-3" />
              Type @ to mention a teammate
            </p>
          )}

          <div className="relative">
            <Textarea
              ref={textareaRef}
              value={content}
              onChange={handleContentChange}
              placeholder={teamMembers.length > 1 ? "Add a note… use @ to mention" : "Add a note..."}
              className="min-h-[60px] text-sm resize-none"
              disabled={addNote.isPending}
            />

            {/* @mention dropdown */}
            {showMentionPopover && filteredMembers.length > 0 && mentionAnchor && (
              <div
                ref={mentionPopoverRef}
                className="absolute z-50 w-full bg-popover border border-border rounded-lg shadow-lg overflow-hidden"
                style={{ top: mentionAnchor.top, left: mentionAnchor.left }}
              >
                {filteredMembers.map((member) => {
                  const label = member.email ?? member.user_id.slice(0, 8);
                  const initials = label.slice(0, 2).toUpperCase();
                  return (
                    <button
                      key={member.user_id}
                      type="button"
                      onMouseDown={(e) => {
                        // Use mousedown to fire before textarea blur
                        e.preventDefault();
                        handleMentionSelect(member);
                      }}
                      className="w-full flex items-center gap-2 px-3 py-2 text-sm hover:bg-muted/60 transition-colors text-left"
                    >
                      <div className="h-5 w-5 rounded-full bg-primary/10 text-primary flex items-center justify-center text-[9px] font-bold shrink-0">
                        {initials}
                      </div>
                      <span className="truncate text-xs">{label}</span>
                    </button>
                  );
                })}
              </div>
            )}
          </div>

          <div className="flex items-center justify-between gap-2">
            <div className="flex items-center gap-1">
              {(Object.keys(NOTE_TYPE_STYLES) as NoteType[]).map((type) => (
                <button
                  key={type}
                  onClick={() => setNoteType(type)}
                  className={cn(
                    "text-xs px-2 py-1 rounded-full font-medium transition-all",
                    noteType === type
                      ? NOTE_TYPE_STYLES[type].className + " ring-1 ring-offset-1 ring-current"
                      : "bg-muted/50 text-muted-foreground hover:bg-muted"
                  )}
                >
                  {NOTE_TYPE_STYLES[type].label}
                </button>
              ))}
            </div>
            <Button
              size="sm"
              className="h-7 text-xs px-3"
              onClick={handleSubmit}
              disabled={!content.trim() || addNote.isPending}
            >
              {addNote.isPending ? <Loader2 className="h-3 w-3 animate-spin" /> : "Post"}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

export type NoteType = "general" | "positive" | "concern" | "flag";

export interface CandidateNote {
  id: string;
  resume_id: string;
  job_id: string;
  author_id: string;
  note_type: NoteType;
  content: string;
  created_at: string;
  updated_at: string;
}

export function useCandidateNotes(resumeId: string | null, jobId: string | null) {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const queryKey = ["candidate-notes", resumeId, jobId];

  const { data: notes = [], isLoading } = useQuery<CandidateNote[]>({
    queryKey,
    queryFn: async () => {
      if (!resumeId || !jobId) return [];
      const { data, error } = await (supabase as any)
        .from("candidate_notes")
        .select("*")
        .eq("resume_id", resumeId)
        .eq("job_id", jobId)
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data ?? [];
    },
    enabled: !!resumeId && !!jobId,
    staleTime: 30_000,
  });

  useEffect(() => {
    if (!resumeId || !jobId) return;
    const channel = supabase
      .channel(`notes-${resumeId}-${jobId}`)
      .on("postgres_changes", {
        event: "*",
        schema: "public",
        table: "candidate_notes",
        filter: `resume_id=eq.${resumeId}`,
      }, () => {
        queryClient.invalidateQueries({ queryKey });
      })
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [resumeId, jobId, queryClient]);

  const addNote = useMutation({
    mutationFn: async ({ content, noteType, mentions }: { content: string; noteType: NoteType; mentions?: string[] }) => {
      const { error } = await (supabase as any)
        .from("candidate_notes")
        .insert({ resume_id: resumeId, job_id: jobId, author_id: user?.id, note_type: noteType, content, mentions: mentions ?? [] });
      if (error) throw error;
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
  });

  const deleteNote = useMutation({
    mutationFn: async (noteId: string) => {
      const { error } = await (supabase as any)
        .from("candidate_notes")
        .delete()
        .eq("id", noteId);
      if (error) throw error;
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
  });

  return { notes, isLoading, addNote, deleteNote, currentUserId: user?.id };
}

