import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

type TeamRole = "owner" | "admin" | "member";

export interface TeamMember {
  id: string;
  user_id: string;
  role: TeamRole;
  joined_at: string;
  email?: string;
}

export interface TeamInvitation {
  id: string;
  email: string;
  role: TeamRole;
  status: string;
  created_at: string;
  expires_at: string;
}

export interface Team {
  id: string;
  name: string;
  owner_id: string;
}

export function useTeam() {
  const { user } = useAuth();
  const userId = user?.id;

  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ["team", userId],
    queryFn: async () => {
      if (!userId) return { team: null, members: [], invitations: [], myRole: null };

      // Get user's team membership (prefer owned team, fallback to any team)
      const { data: allMemberships } = await (supabase as any)
        .from("team_members")
        .select("team_id, role")
        .eq("user_id", userId)
        .order("role");

      // Pick the team where user is owner first, otherwise first membership
      const memberships = (allMemberships ?? []) as { team_id: string; role: string }[];
      const tmData = memberships.find((m) => m.role === "owner") ?? memberships[0] ?? null;

      if (!tmData?.team_id) return { team: null, members: [], invitations: [], myRole: null };

      const teamId = tmData.team_id;

      // Fetch team, members, invitations in parallel
      const [teamRes, membersRes, invitationsRes] = await Promise.all([
        (supabase as any).from("teams").select("id, name, owner_id").eq("id", teamId).single(),
        (supabase as any).from("team_members").select("id, user_id, role, joined_at").eq("team_id", teamId).order("joined_at"),
        (supabase as any).from("team_invitations").select("id, email, role, status, created_at, expires_at").eq("team_id", teamId).eq("status", "pending").order("created_at", { ascending: false }),
      ]);

      const team: Team | null = teamRes.data ?? null;
      const rawMembers = (membersRes.data ?? []) as TeamMember[];
      const invitations = (invitationsRes.data ?? []) as TeamInvitation[];

      // Augment current user's own record with their email; others show user_id until
      // a profiles.email column is available.
      const members = rawMembers.map((m) => ({
        ...m,
        email: m.user_id === userId ? user?.email ?? undefined : undefined,
      }));

      return { team, members, invitations, myRole: tmData.role as TeamRole };
    },
    enabled: !!userId,
    staleTime: 60_000,
  });

  return {
    team: data?.team ?? null,
    members: data?.members ?? [],
    invitations: data?.invitations ?? [],
    myRole: data?.myRole ?? null,
    isLoading,
    error,
    refetch,
  };
}

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import type { ActivityItem } from "@/hooks/useActivityFeed";

export interface TasksByAssignee {
  user_id: string;
  pending: number;
  completed: number;
}

export interface TeamDashboardData {
  totalJobs: number;
  activeCandidates: number;
  pendingTasks: number;
  memberCount: number;
  recentActivity: ActivityItem[];
  tasksByAssignee: TasksByAssignee[];
}

export function useTeamDashboard(teamId: string | null) {
  return useQuery<TeamDashboardData>({
    queryKey: ["team-dashboard", teamId],
    queryFn: async () => {
      if (!teamId) {
        return {
          totalJobs: 0,
          activeCandidates: 0,
          pendingTasks: 0,
          memberCount: 0,
          recentActivity: [],
          tasksByAssignee: [],
        };
      }

      const [
        jobsRes,
        pendingTasksRes,
        membersRes,
        activityRes,
        allTasksRes,
      ] = await Promise.all([
        // Total jobs for this team
        (supabase as any)
          .from("jobs")
          .select("id", { count: "exact", head: true })
          .eq("team_id", teamId),

        // Pending tasks count
        (supabase as any)
          .from("tasks")
          .select("id", { count: "exact", head: true })
          .eq("team_id", teamId)
          .neq("status", "done"),

        // Team members count
        (supabase as any)
          .from("team_members")
          .select("id", { count: "exact", head: true })
          .eq("team_id", teamId),

        // Last 5 activity items
        (supabase as any)
          .from("activity_log")
          .select("*")
          .eq("team_id", teamId)
          .order("created_at", { ascending: false })
          .limit(5),

        // All tasks for assignee summary (limited columns)
        (supabase as any)
          .from("tasks")
          .select("assigned_to, status")
          .eq("team_id", teamId)
          .not("assigned_to", "is", null),
      ]);

      // Active candidates: count resumes linked to this team's jobs
      // We fetch job IDs first, then count resumes
      let activeCandidates = 0;
      const { data: jobIds } = await (supabase as any)
        .from("jobs")
        .select("id")
        .eq("team_id", teamId);

      if (jobIds && jobIds.length > 0) {
        const ids = (jobIds as { id: string }[]).map((j) => j.id);
        const { count } = await (supabase as any)
          .from("resumes")
          .select("id", { count: "exact", head: true })
          .in("job_id", ids);
        activeCandidates = count ?? 0;
      }

      // Build tasks-by-assignee summary
      const tasksByAssignee: TasksByAssignee[] = [];
      const allTasks = (allTasksRes.data ?? []) as { assigned_to: string; status: string }[];
      const assigneeMap = new Map<string, TasksByAssignee>();

      for (const t of allTasks) {
        if (!t.assigned_to) continue;
        if (!assigneeMap.has(t.assigned_to)) {
          assigneeMap.set(t.assigned_to, { user_id: t.assigned_to, pending: 0, completed: 0 });
        }
        const entry = assigneeMap.get(t.assigned_to)!;
        if (t.status === "done") {
          entry.completed += 1;
        } else {
          entry.pending += 1;
        }
      }
      assigneeMap.forEach((v) => tasksByAssignee.push(v));

      return {
        totalJobs: jobsRes.count ?? 0,
        activeCandidates,
        pendingTasks: pendingTasksRes.count ?? 0,
        memberCount: membersRes.count ?? 0,
        recentActivity: (activityRes.data ?? []) as ActivityItem[],
        tasksByAssignee,
      };
    },
    enabled: !!teamId,
    staleTime: 60_000,
  });
}

-- ============================================================
-- TEAM COLLABORATION: Teams, Invitations, Candidate Notes
-- ============================================================

-- ─────────────────────────────────────────────────────────────
-- 1. ENUM
-- ─────────────────────────────────────────────────────────────
CREATE TYPE public.team_role AS ENUM ('owner', 'admin', 'member');

-- ─────────────────────────────────────────────────────────────
-- 2. TABLES
-- ─────────────────────────────────────────────────────────────

CREATE TABLE public.teams (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name        text NOT NULL,
  owner_id    uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.team_members (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  team_id    uuid NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE,
  user_id    uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  role       public.team_role NOT NULL DEFAULT 'member',
  joined_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (team_id, user_id)
);

CREATE TABLE public.team_invitations (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  team_id     uuid NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE,
  email       text NOT NULL,
  role        public.team_role NOT NULL DEFAULT 'member',
  invited_by  uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  status      text NOT NULL DEFAULT 'pending'
                CHECK (status IN ('pending', 'accepted', 'declined', 'expired')),
  token       uuid NOT NULL DEFAULT gen_random_uuid(),
  created_at  timestamptz NOT NULL DEFAULT now(),
  expires_at  timestamptz NOT NULL DEFAULT (now() + interval '7 days'),
  UNIQUE (team_id, email)
);

CREATE TABLE public.candidate_notes (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  resume_id   uuid NOT NULL REFERENCES public.resumes(id) ON DELETE CASCADE,
  job_id      uuid NOT NULL REFERENCES public.jobs(id) ON DELETE CASCADE,
  author_id   uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  note_type   text NOT NULL DEFAULT 'general'
                CHECK (note_type IN ('general', 'positive', 'concern', 'flag')),
  content     text NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

-- ─────────────────────────────────────────────────────────────
-- 3. ADD team_id TO jobs
-- ─────────────────────────────────────────────────────────────

ALTER TABLE public.jobs
  ADD COLUMN IF NOT EXISTS team_id uuid REFERENCES public.teams(id) ON DELETE SET NULL;

-- ─────────────────────────────────────────────────────────────
-- 4. INDEXES
-- ─────────────────────────────────────────────────────────────

CREATE INDEX idx_teams_owner_id          ON public.teams(owner_id);
CREATE INDEX idx_team_members_team_id    ON public.team_members(team_id);
CREATE INDEX idx_team_members_user_id    ON public.team_members(user_id);
CREATE INDEX idx_team_invitations_token  ON public.team_invitations(token);
CREATE INDEX idx_team_invitations_email  ON public.team_invitations(email);
CREATE INDEX idx_candidate_notes_job_id  ON public.candidate_notes(job_id);
CREATE INDEX idx_candidate_notes_resume_id ON public.candidate_notes(resume_id);
CREATE INDEX idx_jobs_team_id            ON public.jobs(team_id);

-- ─────────────────────────────────────────────────────────────
-- 5. TRIGGERS (updated_at)
-- update_updated_at_column() already exists from initial schema
-- ─────────────────────────────────────────────────────────────

CREATE TRIGGER update_teams_updated_at
  BEFORE UPDATE ON public.teams
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

CREATE TRIGGER update_candidate_notes_updated_at
  BEFORE UPDATE ON public.candidate_notes
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

-- ─────────────────────────────────────────────────────────────
-- 6. HELPER FUNCTIONS
-- ─────────────────────────────────────────────────────────────

-- Returns true if _user_id is any member of _team_id
CREATE OR REPLACE FUNCTION public.is_team_member(_user_id uuid, _team_id uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.team_members
    WHERE team_id = _team_id AND user_id = _user_id
  )
$$;

-- Returns true if _user_id is owner or admin of _team_id
CREATE OR REPLACE FUNCTION public.is_team_admin(_user_id uuid, _team_id uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.team_members
    WHERE team_id = _team_id
      AND user_id = _user_id
      AND role IN ('owner', 'admin')
  )
$$;

-- Returns true if _user_id is a team member of the team that owns _job_id
CREATE OR REPLACE FUNCTION public.is_team_member_of_job(_user_id uuid, _job_id uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.jobs j
    JOIN public.team_members tm ON tm.team_id = j.team_id
    WHERE j.id = _job_id
      AND tm.user_id = _user_id
      AND j.team_id IS NOT NULL
  )
$$;

-- ─────────────────────────────────────────────────────────────
-- 7. UPDATE handle_new_user() — add team provisioning
--    Preserves all existing inbox/profile logic; adds:
--      a) personal team creation
--      b) owner team_members row
--      c) auto-accept pending invitations for this email
-- ─────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.handle_new_user()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  raw_email   text;
  local_part  text;
  domain      text;
  base_inbox  text;
  final_inbox text;
  suffix      text;
  attempts    int := 0;
  new_team_id uuid;
  user_name   text;
BEGIN
  -- ── Profile & inbox (existing logic) ──────────────────────
  raw_email := lower(trim(NEW.raw_user_meta_data->>'email'));
  IF raw_email IS NULL OR raw_email = '' THEN
    raw_email := lower(trim(NEW.email));
  END IF;

  SELECT inbound_email_domain INTO domain FROM public.platform_config LIMIT 1;
  IF domain IS NULL OR domain = '' THEN
    domain := 'inbound.rankora.co';
  END IF;

  local_part := split_part(raw_email, '@', 1);
  local_part := regexp_replace(local_part, '[^a-z0-9.\-]', '.', 'g');
  local_part := regexp_replace(local_part, '\.{2,}', '.', 'g');
  local_part := trim(both '.' from local_part);
  IF local_part = '' THEN local_part := 'user'; END IF;

  base_inbox  := local_part || '@' || domain;
  final_inbox := base_inbox;

  WHILE EXISTS (SELECT 1 FROM public.profiles WHERE inbox_email = final_inbox) LOOP
    attempts := attempts + 1;
    suffix := substr(md5(random()::text), 1, 3);
    final_inbox := local_part || '.' || suffix || '@' || domain;
    IF attempts > 10 THEN
      final_inbox := substr(md5(NEW.id::text || now()::text), 1, 12) || '@' || domain;
      EXIT;
    END IF;
  END LOOP;

  INSERT INTO public.profiles (user_id, credits, inbox_email)
  VALUES (NEW.id, 5, final_inbox);

  INSERT INTO public.user_roles (user_id, role)
  VALUES (NEW.id, 'user');

  -- ── Team provisioning (new) ────────────────────────────────
  user_name := COALESCE(
    NULLIF(trim(NEW.raw_user_meta_data->>'full_name'), ''),
    NULLIF(trim(NEW.raw_user_meta_data->>'name'), ''),
    local_part
  );

  INSERT INTO public.teams (name, owner_id)
  VALUES (user_name || '''s Team', NEW.id)
  RETURNING id INTO new_team_id;

  INSERT INTO public.team_members (team_id, user_id, role)
  VALUES (new_team_id, NEW.id, 'owner');

  -- ── Auto-accept pending invitations for this email ─────────
  -- Update team_invitations status and insert team_members rows
  -- for any pending, non-expired invitations addressed to this email.
  INSERT INTO public.team_members (team_id, user_id, role)
  SELECT ti.team_id, NEW.id, ti.role
  FROM public.team_invitations ti
  WHERE lower(ti.email) = lower(raw_email)
    AND ti.status = 'pending'
    AND ti.expires_at > now()
  ON CONFLICT (team_id, user_id) DO NOTHING;

  UPDATE public.team_invitations
  SET status = 'accepted'
  WHERE lower(email) = lower(raw_email)
    AND status = 'pending'
    AND expires_at > now();

  RETURN NEW;
END;
$function$;

-- ─────────────────────────────────────────────────────────────
-- 8. BACKFILL: create teams for existing users
-- ─────────────────────────────────────────────────────────────

DO $$
DECLARE
  rec           RECORD;
  new_team_id   uuid;
  user_name     text;
BEGIN
  -- For every auth user that has a profile but no team yet
  FOR rec IN
    SELECT u.id, u.email, u.raw_user_meta_data
    FROM auth.users u
    WHERE NOT EXISTS (
      SELECT 1 FROM public.team_members tm WHERE tm.user_id = u.id AND tm.role = 'owner'
    )
  LOOP
    user_name := COALESCE(
      NULLIF(trim(rec.raw_user_meta_data->>'full_name'), ''),
      NULLIF(trim(rec.raw_user_meta_data->>'name'), ''),
      split_part(lower(coalesce(rec.email, 'user')), '@', 1)
    );
    IF user_name = '' THEN user_name := 'user'; END IF;

    INSERT INTO public.teams (name, owner_id)
    VALUES (user_name || '''s Team', rec.id)
    RETURNING id INTO new_team_id;

    INSERT INTO public.team_members (team_id, user_id, role)
    VALUES (new_team_id, rec.id, 'owner')
    ON CONFLICT DO NOTHING;
  END LOOP;

  -- Backfill team_id on jobs that don't have one yet
  UPDATE public.jobs j
  SET team_id = (
    SELECT t.id
    FROM public.teams t
    WHERE t.owner_id = j.user_id
    LIMIT 1
  )
  WHERE j.team_id IS NULL;
END;
$$;

-- ─────────────────────────────────────────────────────────────
-- 9. TRIGGER: auto-set team_id on new jobs
-- ─────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.auto_set_job_team_id()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
AS $$
BEGIN
  IF NEW.team_id IS NULL THEN
    SELECT id INTO NEW.team_id
    FROM public.teams
    WHERE owner_id = NEW.user_id
    LIMIT 1;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER auto_set_job_team_id
  BEFORE INSERT ON public.jobs
  FOR EACH ROW
  EXECUTE FUNCTION public.auto_set_job_team_id();

-- ─────────────────────────────────────────────────────────────
-- 10. ROW LEVEL SECURITY
-- ─────────────────────────────────────────────────────────────

ALTER TABLE public.teams             ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.team_members      ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.team_invitations  ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.candidate_notes   ENABLE ROW LEVEL SECURITY;

-- ── teams ─────────────────────────────────────────────────────
-- Members can see teams they belong to
CREATE POLICY "Team members can view their team"
  ON public.teams FOR SELECT TO authenticated
  USING (public.is_team_member(auth.uid(), id));

-- Only the owner can update team name
CREATE POLICY "Team owner can update team"
  ON public.teams FOR UPDATE TO authenticated
  USING (owner_id = auth.uid())
  WITH CHECK (owner_id = auth.uid());

-- No direct INSERT — teams are created by handle_new_user trigger
-- (INSERT is done via service role in trigger context)

-- ── team_members ──────────────────────────────────────────────
-- All team members can see the full roster
CREATE POLICY "Team members can view roster"
  ON public.team_members FOR SELECT TO authenticated
  USING (public.is_team_member(auth.uid(), team_id));

-- Admins and owners can add new members
CREATE POLICY "Team admins can add members"
  ON public.team_members FOR INSERT TO authenticated
  WITH CHECK (public.is_team_admin(auth.uid(), team_id));

-- Admins and owners can update member roles
CREATE POLICY "Team admins can update member roles"
  ON public.team_members FOR UPDATE TO authenticated
  USING (public.is_team_admin(auth.uid(), team_id))
  WITH CHECK (public.is_team_admin(auth.uid(), team_id));

-- Admins can remove members; members can remove themselves (leave)
CREATE POLICY "Team admins can remove members"
  ON public.team_members FOR DELETE TO authenticated
  USING (
    public.is_team_admin(auth.uid(), team_id)
    OR user_id = auth.uid()
  );

-- ── team_invitations ──────────────────────────────────────────
CREATE POLICY "Team admins can manage invitations"
  ON public.team_invitations FOR SELECT TO authenticated
  USING (public.is_team_admin(auth.uid(), team_id));

CREATE POLICY "Team admins can create invitations"
  ON public.team_invitations FOR INSERT TO authenticated
  WITH CHECK (public.is_team_admin(auth.uid(), team_id));

CREATE POLICY "Team admins can update invitations"
  ON public.team_invitations FOR UPDATE TO authenticated
  USING (public.is_team_admin(auth.uid(), team_id))
  WITH CHECK (public.is_team_admin(auth.uid(), team_id));

CREATE POLICY "Team admins can delete invitations"
  ON public.team_invitations FOR DELETE TO authenticated
  USING (public.is_team_admin(auth.uid(), team_id));

-- ── candidate_notes ───────────────────────────────────────────
-- Team members can see notes on jobs in their team
CREATE POLICY "Team members can view candidate notes"
  ON public.candidate_notes FOR SELECT TO authenticated
  USING (
    public.is_job_owner(auth.uid(), job_id)
    OR public.is_team_member_of_job(auth.uid(), job_id)
  );

-- Team members can add notes to jobs in their team
CREATE POLICY "Team members can add candidate notes"
  ON public.candidate_notes FOR INSERT TO authenticated
  WITH CHECK (
    author_id = auth.uid()
    AND (
      public.is_job_owner(auth.uid(), job_id)
      OR public.is_team_member_of_job(auth.uid(), job_id)
    )
  );

-- Authors can update their own notes
CREATE POLICY "Authors can update own notes"
  ON public.candidate_notes FOR UPDATE TO authenticated
  USING (author_id = auth.uid())
  WITH CHECK (author_id = auth.uid());

-- Authors can delete own notes; team admins can delete any note
CREATE POLICY "Authors and admins can delete notes"
  ON public.candidate_notes FOR DELETE TO authenticated
  USING (
    author_id = auth.uid()
    OR EXISTS (
      SELECT 1
      FROM public.jobs j
      WHERE j.id = candidate_notes.job_id
        AND public.is_team_admin(auth.uid(), j.team_id)
    )
  );

-- ─────────────────────────────────────────────────────────────
-- 11. UPDATE EXISTING SELECT POLICIES to include team members
-- ─────────────────────────────────────────────────────────────

-- ── jobs ──────────────────────────────────────────────────────
DROP POLICY IF EXISTS "Users read own jobs" ON public.jobs;
CREATE POLICY "Users read own jobs"
  ON public.jobs FOR SELECT TO authenticated
  USING (
    user_id = auth.uid()
    OR public.is_team_member_of_job(auth.uid(), id)
  );

-- ── resumes ───────────────────────────────────────────────────
DROP POLICY IF EXISTS "Users read own resumes" ON public.resumes;
CREATE POLICY "Users read own resumes"
  ON public.resumes FOR SELECT TO authenticated
  USING (
    public.is_job_owner(auth.uid(), job_id)
    OR public.is_team_member_of_job(auth.uid(), job_id)
  );

-- ── results ───────────────────────────────────────────────────
DROP POLICY IF EXISTS "Users read own results" ON public.results;
CREATE POLICY "Users read own results"
  ON public.results FOR SELECT TO authenticated
  USING (
    EXISTS (
      SELECT 1
      FROM public.resumes r
      JOIN public.jobs j ON r.job_id = j.id
      WHERE r.id = results.resume_id
        AND (
          j.user_id = auth.uid()
          OR public.is_team_member_of_job(auth.uid(), j.id)
        )
    )
  );

-- ── candidate_stages ──────────────────────────────────────────
DROP POLICY IF EXISTS "Users can view stages for own jobs" ON public.candidate_stages;
CREATE POLICY "Users can view stages for own jobs"
  ON public.candidate_stages FOR SELECT TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.jobs
      WHERE jobs.id = candidate_stages.job_id
        AND (
          jobs.user_id = auth.uid()
          OR public.is_team_member_of_job(auth.uid(), jobs.id)
        )
    )
  );

-- ── stage_history ─────────────────────────────────────────────
DROP POLICY IF EXISTS "Users can view stage history for own jobs" ON public.stage_history;
CREATE POLICY "Users can view stage history for own jobs"
  ON public.stage_history FOR SELECT TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.jobs
      WHERE jobs.id = stage_history.job_id
        AND (
          jobs.user_id = auth.uid()
          OR public.is_team_member_of_job(auth.uid(), jobs.id)
        )
    )
  );

-- ── applications ──────────────────────────────────────────────
DROP POLICY IF EXISTS "applications_owner_select" ON public.applications;
CREATE POLICY "applications_owner_select"
  ON public.applications FOR SELECT TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.jobs
      WHERE jobs.id = applications.job_id
        AND (
          jobs.user_id = auth.uid()
          OR public.is_team_member_of_job(auth.uid(), jobs.id)
        )
    )
  );

